import type { QuizRoom } from './quiz-room-model';

export const QuizRoomParticipantAvatarColorKeyToLabel = {
  'AvatarColorKey0': 'Yellow',
  'AvatarColorKey1': 'LightBlue',
  'AvatarColorKey2': 'White'
} as const;
export type QuizRoomParticipantAvatarColorKey = keyof typeof QuizRoomParticipantAvatarColorKeyToLabel;

export interface QuizRoomParticipant {
  /**
   * @displayName Quiz Room Participant ID
   * @description Unique system identifier - GUID generated by system
   * @uiConstraints NEVER create input fields for this ID
   */
  id: string;
  /**
   * @displayName Display Name
   * @description Human-readable record identifier
   * @validationRule Required for create/update operations
   */
  displayName: string;
  /**
   * @displayName Avatar Color
   * @validationRule Required for create/update operations
   */
  avatarColorKey: QuizRoomParticipantAvatarColorKey;
  /**
   * @displayName Joined At
   * @validationRule Required for create/update operations
   */
  joinedAt: string;
  /**
   * @displayName Last Answer Correct
   * @validationRule Required for create/update operations
   */
  lastAnswerCorrect: boolean;
  /**
   * @displayName Room ID
   * @validationRule Required for create/update operations
   */
  roomID: Pick<QuizRoom, 'id' | 'roomID'>;
  /**
   * @displayName Score
   * @validationRule Required for create/update operations
   */
  score: number;
  /**
   * @displayName User ID
   * @validationRule Required for create/update operations
   */
  userID: string;
}

export const _QuizRoomParticipant = 'QuizRoomParticipant' as const;